		private void CreateSearchDataListCore(int indexGroup, global::Dpr.Message.MessageMsgFile defaultMsgFile) {
			switch (SearchType)
			{
				case BoxWindow.SearchType.Pokemon:
					{
						var monsNameMsgFile = MessageManager.Instance.GetMsgFile("ss_monsname");
						LastSelectValues = new List<int>();
						int count = BoxWindow.SearchIndexData.MonsterName.Length;
						for (int i = 0; i < count; i++)
						{
							if (BoxWindow.SearchIndexData.MonsterName[i].IndexGroup == indexGroup || MaxDepth == 0)
							{
								string messageID = BoxWindow.SearchIndexData.MonsterName[i].MessageID;
								int monsNo = 0;
								int.TryParse(messageID.Substring(messageID.Length - 3), out monsNo);
								if (ZukanWork.IsGet((uint)monsNo))
								{
									MessageWordSetHelper.SetGlossaryWordFromMsgFile(0, monsNameMsgFile, messageID);
									int sex = UIManager.Instance.GetSearchPokeIconSex((Pml.MonsNo)monsNo);
									UIManager.Instance.LoadSpritePokemon((Pml.MonsNo)monsNo, 0, (Pml.Sex)sex, RareType.NOT_RARE, false, sprite =>
									{
										AddSearchList(defaultMsgFile, BoxWindow.SearchMsgData[CurrentIndex].nameId, sprite);
									});
									LastSelectValues.Add(monsNo);
								}
							}
						}
					}
					break;
				case BoxWindow.SearchType.Type1:
				case BoxWindow.SearchType.Type2:
					for (int i = 0; i < (int)Pml.PokeType.NUMS; i++)
					{
						MessageWordSetHelper.SetWazaTypeWord(0, (Pml.PokeType)i);
						AddSearchList(defaultMsgFile, BoxWindow.SearchMsgData[CurrentIndex].nameId);
					}
					break;
				case BoxWindow.SearchType.Waza:
					{
						var wazaNameMsgFile = MessageManager.Instance.GetMsgFile("ss_wazaname");
						LastSelectValues = new List<int>();
						int count = BoxWindow.SearchIndexData.WazaName.Length;
						for (int i = 0; i < count; i++)
						{
							if (BoxWindow.SearchIndexData.WazaName[i].IndexGroup == indexGroup || MaxDepth == 0)
							{
								string messageID = BoxWindow.SearchIndexData.WazaName[i].MessageID;
								if (UIManager.Instance.IsDisplayWazaString(messageID))
								{
									MessageWordSetHelper.SetGlossaryWordFromMsgFile(0, wazaNameMsgFile, messageID);
									AddSearchList(defaultMsgFile, BoxWindow.SearchMsgData[CurrentIndex].nameId);
									int wazaNo = 0;
									int.TryParse(messageID.Substring(messageID.Length - 3), out wazaNo);
									LastSelectValues.Add(wazaNo);
								}
							}
						}
					}
					break;
				case BoxWindow.SearchType.Machine:
					{
						ItemWork.GetItemInfosByCategory(Dpr.Item.ItemInfo.CategoryType.WazaMachine);
						LastSelectValues = new List<int>();
						uint machineMax = Pml.Item.ItemData.GetWazaMashineMax();
						for (int i = 0; i < machineMax; i++)
						{
							if (Pml.Item.ItemData.IsValid((ushort)Pml.Item.ItemData.GetWazaMashineItemNo((byte)i)))
							{
								MessageWordSetHelper.SetWazaNameWord(0, Pml.Item.ItemData.GetWazaMashineWaza((byte)i));
								AddSearchList(defaultMsgFile, BoxWindow.SearchMsgData[CurrentIndex].nameId);
								LastSelectValues.Add(i);
							}
						}
					}
					break;
				case BoxWindow.SearchType.Tokusei:
					{
						var tokuseiMsgFile = MessageManager.Instance.GetMsgFile("ss_tokusei");
						LastSelectValues = new List<int>();
						int count = BoxWindow.SearchIndexData.Tokusei.Length;
						for (int i = 0; i < count; i++)
						{
							if (BoxWindow.SearchIndexData.Tokusei[i].IndexGroup == indexGroup || MaxDepth == 0)
							{
								string messageID = BoxWindow.SearchIndexData.Tokusei[i].MessageID;
								if (UIManager.Instance.IsDisplayTokuseiString(messageID))
								{
									MessageWordSetHelper.SetGlossaryWordFromMsgFile(0, tokuseiMsgFile, messageID);
									AddSearchList(defaultMsgFile, BoxWindow.SearchMsgData[CurrentIndex].nameId);
									int tokuseiNo = 0;
									int.TryParse(messageID.Substring(messageID.Length - 3), out tokuseiNo);
									LastSelectValues.Add(tokuseiNo);
								}
							}
						}
					}
					break;
				case BoxWindow.SearchType.Personality:
					for (int i = 0; i < (int)Seikaku.NUM; i++)
					{
						MessageWordSetHelper.SetSeikakuWord(0, (Seikaku)i);
						AddSearchList(defaultMsgFile, BoxWindow.SearchMsgData[CurrentIndex].nameId);
					}
					break;
				case BoxWindow.SearchType.Sex:
					for (int i = 0; i < (int)Pml.Sex.NUM; i++)
						AddSearchList(defaultMsgFile, GetCalcTextID(BoxWindow.SearchMsgData[CurrentIndex].nameId, i));
					break;
				case BoxWindow.SearchType.Item:
					for (int i = 0; i < (int)BoxWindow.SearchItem.MAX; i++)
						AddSearchList(defaultMsgFile, GetCalcTextID(BoxWindow.SearchMsgData[CurrentIndex].nameId, i));
					break;
				case BoxWindow.SearchType.Mark:
					for (int i = 0; i < (int)BoxMark.MARK_NUM; i++)
						SearchItemList.Add(new BoxWindow.SearchItemData(string.Format("{0}", (SearchData.mark >> (i * 2)) & 3)));
					foreach (BoxSearchItem item in _searchTypeScroller.ScrollItems)
					{
						if (item.GetIndex() == (int)BoxWindow.SearchType.Mark)
						{
							for (int i = 0; i < item.MarkImages.Length; i++)
								SearchItemList[i].MarkSprite = item.MarkImages[i].sprite;
							break;
						}
					}
					break;
				case BoxWindow.SearchType.Team:
					{
						var boxNameMsgFile = MessageManager.Instance.GetMsgFile(BoxWindow.BoxNameFileName);
						for (int i = 0; i < Dpr.Box.BoxWork.TEAM_MAX; i++)
						{
							string teamName = Dpr.Box.BoxWork.GetTeamName(i);
							if (string.IsNullOrEmpty(teamName))
								MessageWordSetHelper.SetGlossaryWordFromMsgFile(0, boxNameMsgFile, BoxParty.GetTeamNameID(i));
							else
								MessageWordSetHelper.SetStringWord(0, teamName);
							AddSearchList(defaultMsgFile, BoxWindow.SearchMsgData[CurrentIndex].nameId);
						}
					}
					break;
			}
		}
		private string GetCalcTextID(string baseTextID, int index) {
			string head = baseTextID.Substring(0, 7);
			int number = 0;
			int.TryParse(baseTextID.Substring(7, 3), out number);
			return string.Format("{0}{1}", head, number + index);
		}
		private void AddSearchList(global::Dpr.Message.MessageMsgFile msgFile, string messageID, global::UnityEngine.Sprite sprite = null) {
			var textModel = msgFile.GetTextDataModel(messageID);
			textModel.ApplyFormat();
			SearchItemList.Add(new BoxWindow.SearchItemData(textModel.GetAllText(), sprite));
		}
		private int GetCountOfIndexGroup(global::Dpr.UI.BoxWindow.SearchType type, int group) {
			int count = 0;
			int length = 0;
			switch (type)
			{
				case BoxWindow.SearchType.Pokemon:
					length = BoxWindow.SearchIndexData.MonsterName.Length;
					break;
				case BoxWindow.SearchType.Waza:
					length = BoxWindow.SearchIndexData.WazaName.Length;
					break;
				case BoxWindow.SearchType.Tokusei:
					length = BoxWindow.SearchIndexData.Tokusei.Length;
					break;
			}
			for (int i = 0; i < length; i++)
			{
				bool isDisplay = true;
				int indexGroup = -1;
				switch (type)
				{
					case BoxWindow.SearchType.Pokemon:
						{
							string messageID = BoxWindow.SearchIndexData.MonsterName[i].MessageID;
							indexGroup = BoxWindow.SearchIndexData.MonsterName[i].IndexGroup;
							int monsNo = 0;
							int.TryParse(messageID.Substring(messageID.Length - 3), out monsNo);
							if (!ZukanWork.IsGet((uint)monsNo))
								continue;
						}
						break;
					case BoxWindow.SearchType.Waza:
						indexGroup = BoxWindow.SearchIndexData.WazaName[i].IndexGroup;
						isDisplay = UIManager.Instance.IsDisplayWazaString(BoxWindow.SearchIndexData.WazaName[i].MessageID);
						break;
					case BoxWindow.SearchType.Tokusei:
						indexGroup = BoxWindow.SearchIndexData.Tokusei[i].IndexGroup;
						isDisplay = UIManager.Instance.IsDisplayTokuseiString(BoxWindow.SearchIndexData.Tokusei[i].MessageID);
						break;
				}
				if (isDisplay && indexGroup == group)
					count++;
				if (indexGroup > group)
					break;
			}
			return count;
		}
		public void SetSearchData(global::Dpr.UI.BoxWindow.SEARCH_DATA searchData, int subIndex, bool isApplyPanel = false) {
			switch (SearchType)
			{
				case BoxWindow.SearchType.Pokemon:
					if (subIndex == 0 && CurrentDepth == MaxDepth)
						searchData.mons = Pml.MonsNo.NULL;
					else if (CurrentDepth == 0)
						searchData.mons = (Pml.MonsNo)LastSelectValues[CurrentDepth == MaxDepth ? subIndex - 1 : subIndex];
					break;
				case BoxWindow.SearchType.Type1:
					searchData.type1 = subIndex == 0 ? Pml.PokeType.NULL : (Pml.PokeType)(subIndex - 1);
					break;
				case BoxWindow.SearchType.Type2:
					searchData.type2 = subIndex == 0 ? Pml.PokeType.NULL : (Pml.PokeType)(subIndex - 1);
					break;
				case BoxWindow.SearchType.Waza:
					if (subIndex == 0 && CurrentDepth == MaxDepth)
						searchData.waza = Pml.WazaNo.NULL;
					else if (CurrentDepth == 0)
						searchData.waza = (Pml.WazaNo)LastSelectValues[CurrentDepth == MaxDepth ? subIndex - 1 : subIndex];
					break;
				case BoxWindow.SearchType.Machine:
					searchData.waza_machine = subIndex == 0 ? int.MaxValue : LastSelectValues[subIndex - 1];
					break;
				case BoxWindow.SearchType.Tokusei:
					if (subIndex == 0 && CurrentDepth == MaxDepth)
						searchData.tokusei = Pml.TokuseiNo.NULL;
					else if (CurrentDepth == 0)
						searchData.tokusei = (Pml.TokuseiNo)LastSelectValues[CurrentDepth == MaxDepth ? subIndex - 1 : subIndex];
					break;
				case BoxWindow.SearchType.Personality:
					searchData.seikaku = subIndex == 0 ? Seikaku.NUM : (Seikaku)(subIndex - 1);
					break;
				case BoxWindow.SearchType.Sex:
					searchData.sex = subIndex == 0 ? Pml.Sex.NUM : (Pml.Sex)(subIndex - 1);
					break;
				case BoxWindow.SearchType.Item:
					searchData.item = subIndex == 0 ? BoxWindow.SearchItem.NONE : (BoxWindow.SearchItem)(subIndex - 1);
					break;
				case BoxWindow.SearchType.Mark:
					_markIndex = (BoxMark)subIndex;
					break;
				case BoxWindow.SearchType.Team:
					searchData.team = subIndex == 0 ? Dpr.Box.BoxWork.TEAM_MAX : subIndex - 1;
					break;
				default:
					goto ApplyPanel;
			}
			DepthIndexes[CurrentDepth] = subIndex;
		ApplyPanel:
			if (isApplyPanel)
				SetSelectedItemText(SearchItemList[subIndex].Label);
		}
		public int GetSubIndex() {
			switch (SearchType)
			{
				case BoxWindow.SearchType.Pokemon:
				case BoxWindow.SearchType.Waza:
				case BoxWindow.SearchType.Tokusei:
					return DepthIndexes[CurrentDepth];
				case BoxWindow.SearchType.Type1:
					return SearchData.type1 == Pml.PokeType.NULL ? 0 : (int)(SearchData.type1 + 1);
				case BoxWindow.SearchType.Type2:
					return SearchData.type2 == Pml.PokeType.NULL ? 0 : (int)(SearchData.type2 + 1);
				case BoxWindow.SearchType.Machine:
					return SearchData.waza_machine == int.MaxValue ? 0 : SearchData.waza_machine;
				case BoxWindow.SearchType.Personality:
					return SearchData.seikaku == Seikaku.NUM ? 0 : (int)SearchData.seikaku + 1;
				case BoxWindow.SearchType.Sex:
					return SearchData.sex == Pml.Sex.NUM ? 0 : (int)(SearchData.sex + 1);
				case BoxWindow.SearchType.Item:
					return SearchData.item == BoxWindow.SearchItem.NONE ? 0 : (int)SearchData.item + 1;
				case BoxWindow.SearchType.Mark:
					return (int)_markIndex;
				case BoxWindow.SearchType.Team:
					return SearchData.team == Dpr.Box.BoxWork.TEAM_MAX ? 0 : SearchData.team + 1;
				default:
					return 0;
			}
		}
		public void ClearSearchData() {
			SearchData.Clear();
			for (int i = 0; i < _selectedItemList.Count; i++)
				_selectedItemList[i] = "";
			foreach (BoxSearchItem item in _searchTypeScroller.ScrollItems)
			{
				item.ResetStatus();
				if (item.GetIndex() == (int)BoxWindow.SearchType.Mark)
					item.SetMark(0);
			}
		}
		private int GetNoFromMessageID(string messageID) {
			int number = 0;
			int.TryParse(messageID.Substring(messageID.Length - 3), out number);
			return number;
		}
		public BoxSearchPanel() { }
	}
}
